    bind("ForceClear","nothing",{"force"},[this](auto& vm,auto args){std::get<ScriptForce>(object(args[0],NativeKind::Force).state).players=0;return vm.nothing();});
    bind("ForceAddPlayer","nothing",{"force","player"},[this](auto& vm,auto args){auto id=playerId(args[1]);std::get<ScriptForce>(object(args[0],NativeKind::Force).state).players|=1u<<id;return vm.nothing();});
    bind("ForceRemovePlayer","nothing",{"force","player"},[this](auto& vm,auto args){auto id=playerId(args[1]);std::get<ScriptForce>(object(args[0],NativeKind::Force).state).players&=~(1u<<id);return vm.nothing();});
    bind("IsPlayerInForce","boolean",{"player","force"},[this](auto& vm,auto args){auto id=playerId(args[0]);return vm.boolean((std::get<ScriptForce>(object(args[1],NativeKind::Force).state).players&(1u<<id))!=0);});
    auto players=[this](jass::Value force,jass::Value predicate,unsigned limit,const std::function<bool(unsigned)>& include){object(force,NativeKind::Force);auto filter=expression(predicate);unsigned count=0,mask=0;for(unsigned id=0;id<16 && count<limit;++id)if(include(id)){auto context=contexts_.empty()?ScriptContext{}:contexts_.back();context.filterPlayer=handleBase+id;contexts_.push_back(context);ContextPop guard{contexts_};if(evaluate(filter)){mask|=1u<<id;++count;}}std::get<ScriptForce>(object(force,NativeKind::Force).state).players=mask;};
    bind("ForceEnumPlayers","nothing",{"force","boolexpr"},[players](auto& vm,auto args){players(args[0],args[1],16,[](unsigned){return true;});return vm.nothing();});
    bind("ForceEnumPlayersCounted","nothing",{"force","boolexpr","integer"},[players](auto& vm,auto args){auto count=std::bit_cast<std::int32_t>(args[2].bits);players(args[0],args[1],unsigned(std::max(0,count)),[](unsigned){return true;});return vm.nothing();});
    for(auto [name,allies]:std::initializer_list<std::pair<const char*,bool>>{{"ForceEnumAllies",true},{"ForceEnumEnemies",false}})bind(name,"nothing",{"force","player","boolexpr"},[this,players,allies](auto& vm,auto args){auto owner=playerId(args[1]);players(args[0],args[2],16,[&](unsigned id){bool ally=id==owner || (config_.players[owner].alliances[id]&1u)!=0;return ally==allies;});return vm.nothing();});
    bind("ForForce","nothing",{"force","code"},[this](auto& vm,auto args){auto mask=std::get<ScriptForce>(object(args[0],NativeKind::Force).state).players;for(unsigned id=0;id<16;++id)if(mask&(1u<<id)){auto context=contexts_.empty()?ScriptContext{}:contexts_.back();context.enumPlayer=handleBase+id;contexts_.push_back(context);ContextPop guard{contexts_};runtime_.invoke(args[1]);}return vm.nothing();});
    bind("ForGroup","nothing",{"group","code"},[this](auto& vm,auto args){auto units=std::get<Group>(object(args[0],NativeKind::Group).state).units;for(auto id:units)if(alive(id,NativeKind::Unit)){auto context=contexts_.empty()?ScriptContext{}:contexts_.back();context.enumUnit=id;contexts_.push_back(context);ContextPop guard{contexts_};runtime_.invoke(args[1]);}return vm.nothing();});
    auto enumerate=[this](jass::Value group,jass::Value predicate,unsigned limit,const std::function<bool(const UnitState&)>& include){object(group,NativeKind::Group);auto filter=expression(predicate);std::vector<std::uint32_t> result;if(!filter){for(auto& [id,unit]:units_){if(result.size()>=limit)break;if(alive(id,NativeKind::Unit) && include(*unit))result.push_back(id);}std::get<Group>(object(group,NativeKind::Group).state).units=std::move(result);return;}std::vector<std::pair<std::uint32_t,std::shared_ptr<UnitState>>> snapshot(units_.begin(),units_.end());for(auto& [id,unit]:snapshot)if(result.size()<limit && alive(id,NativeKind::Unit) && include(*unit)){auto context=contexts_.empty()?ScriptContext{}:contexts_.back();context.filterUnit=id;contexts_.push_back(context);ContextPop guard{contexts_};if(evaluate(filter) && alive(id,NativeKind::Unit))result.push_back(id);}std::get<Group>(object(group,NativeKind::Group).state).units=std::move(result);};
    bind("GroupEnumUnitsOfPlayer","nothing",{"group","player","boolexpr"},[this,enumerate](auto& vm,auto args){auto owner=playerId(args[1]);enumerate(args[0],args[2],1048576,[owner](auto& unit){return unit.owner==owner;});return vm.nothing();});
    for(auto [name,counted]:std::initializer_list<std::pair<const char*,bool>>{{"GroupEnumUnitsOfType",false},{"GroupEnumUnitsOfTypeCounted",true}}){auto run=[this,enumerate,counted](auto& vm,auto args){auto type=args[1].text?definitions().unitId(*args[1].text):0;unsigned limit=counted?unsigned(std::max(0,std::bit_cast<std::int32_t>(args[3].bits))):1048576;enumerate(args[0],args[2],limit,[type](auto& unit){return type && unit.type==type;});return vm.nothing();};if(counted)bind(name,"nothing",{"group","string","boolexpr","integer"},run);else bind(name,"nothing",{"group","string","boolexpr"},run);}
    for(auto [name,counted]:std::initializer_list<std::pair<const char*,bool>>{{"GroupEnumUnitsInRect",false},{"GroupEnumUnitsInRectCounted",true}}){auto run=[this,enumerate,counted](auto& vm,auto args){auto rect=std::get<WorldRect>(object(args[1],NativeKind::Rect).state);auto left=std::bit_cast<float>(rect.minX.bits()),right=std::bit_cast<float>(rect.maxX.bits()),bottom=std::bit_cast<float>(rect.minY.bits()),top=std::bit_cast<float>(rect.maxY.bits());unsigned limit=counted?unsigned(std::max(0,std::bit_cast<std::int32_t>(args[3].bits))):1048576;enumerate(args[0],args[2],limit,[=](auto& unit){auto x=std::bit_cast<float>(unit.x.bits()),y=std::bit_cast<float>(unit.y.bits());return x>=left && x<=right && y>=bottom && y<=top;});return vm.nothing();};if(counted)bind(name,"nothing",{"group","rect","boolexpr","integer"},run);else bind(name,"nothing",{"group","rect","boolexpr"},run);}
    for(auto [name,counted]:std::initializer_list<std::pair<const char*,bool>>{{"GroupEnumUnitsInRange",false},{"GroupEnumUnitsInRangeCounted",true}}){auto run=[enumerate,counted](auto& vm,auto args){auto x=coordinate(args[1]),y=coordinate(args[2]),radius=coordinate(args[3]);if(radius<0)throw std::runtime_error("Negative group range");unsigned limit=counted?unsigned(std::max(0,std::bit_cast<std::int32_t>(args[5].bits))):1048576;enumerate(args[0],args[4],limit,[=](auto& unit){double dx=double(std::bit_cast<float>(unit.x.bits()))-x,dy=double(std::bit_cast<float>(unit.y.bits()))-y;return dx*dx+dy*dy<=double(radius)*radius;});return vm.nothing();};if(counted)bind(name,"nothing",{"group","real","real","real","boolexpr","integer"},run);else bind(name,"nothing",{"group","real","real","real","boolexpr"},run);}
    for(auto [name,counted]:std::initializer_list<std::pair<const char*,bool>>{{"GroupEnumUnitsInRangeOfLoc",false},{"GroupEnumUnitsInRangeOfLocCounted",true}}){auto run=[this,enumerate,counted](auto& vm,auto args){auto point=std::get<WorldPoint>(object(args[1],NativeKind::Location).state);auto x=std::bit_cast<float>(point.x.bits()),y=std::bit_cast<float>(point.y.bits()),radius=coordinate(args[2]);if(radius<0)throw std::runtime_error("Negative group range");unsigned limit=counted?unsigned(std::max(0,std::bit_cast<std::int32_t>(args[4].bits))):1048576;enumerate(args[0],args[3],limit,[=](auto& unit){double dx=double(std::bit_cast<float>(unit.x.bits()))-x,dy=double(std::bit_cast<float>(unit.y.bits()))-y;return dx*dx+dy*dy<=double(radius)*radius;});return vm.nothing();};if(counted)bind(name,"nothing",{"group","location","real","boolexpr","integer"},run);else bind(name,"nothing",{"group","location","real","boolexpr"},run);}
    auto groupOrder=[this](auto& vm,jass::Value group,const char* native,std::span<const jass::Value> arguments){auto members=std::get<Group>(object(group,NativeKind::Group).state).units;bool accepted=false;for(auto id:members)if(alive(id,NativeKind::Unit)){std::vector<jass::Value> values;values.reserve(arguments.size()+1);values.push_back(vm.handle("unit",id));values.insert(values.end(),arguments.begin(),arguments.end());if(vm.invoke(native,values).bits)accepted=true;}return vm.boolean(accepted);};
    bind("GroupImmediateOrder","boolean",{"group","string"},[groupOrder](auto& vm,auto a){return groupOrder(vm,a[0],"IssueImmediateOrder",a.subspan(1));});
    bind("GroupImmediateOrderById","boolean",{"group","integer"},[groupOrder](auto& vm,auto a){return groupOrder(vm,a[0],"IssueImmediateOrderById",a.subspan(1));});
    bind("GroupPointOrder","boolean",{"group","string","real","real"},[groupOrder](auto& vm,auto a){return groupOrder(vm,a[0],"IssuePointOrder",a.subspan(1));});
    bind("GroupPointOrderLoc","boolean",{"group","string","location"},[groupOrder](auto& vm,auto a){return groupOrder(vm,a[0],"IssuePointOrderLoc",a.subspan(1));});
    bind("GroupPointOrderById","boolean",{"group","integer","real","real"},[groupOrder](auto& vm,auto a){return groupOrder(vm,a[0],"IssuePointOrderById",a.subspan(1));});
    bind("GroupPointOrderByIdLoc","boolean",{"group","integer","location"},[groupOrder](auto& vm,auto a){return groupOrder(vm,a[0],"IssuePointOrderByIdLoc",a.subspan(1));});
    bind("GroupTargetOrder","boolean",{"group","string","widget"},[groupOrder](auto& vm,auto a){return groupOrder(vm,a[0],"IssueTargetOrder",a.subspan(1));});
    bind("GroupTargetOrderById","boolean",{"group","integer","widget"},[groupOrder](auto& vm,auto a){return groupOrder(vm,a[0],"IssueTargetOrderById",a.subspan(1));});
    bind("IsUnitSelected","boolean",{"unit","player"},[this](auto& vm,auto a){auto owner=playerId(a[1]);if(localPlayer_ && *localPlayer_==owner)syncLocalSelection();return vm.boolean(alive(a[0].bits,NativeKind::Unit) && synchronizedSelections_[owner].contains(a[0].bits));});
    bind("SyncSelections","nothing",{},[this](auto& vm,auto){syncSelections(vm);return vm.nothing();});
    bind("GroupEnumUnitsSelected","nothing",{"group","player","boolexpr"},[this,enumerate](auto& vm,auto args){auto id=playerId(args[1]);auto view=selectionSyncViews_.find(vm.currentThread());std::set<std::uint32_t> selected;if(experimentalSelectionSync_ && view!=selectionSyncViews_.end())selected=(*view->second)[id];else if(experimentalSelectionSync_ && selectionSyncLatest_)selected=(*selectionSyncLatest_)[id];else{if(localPlayer_ && *localPlayer_==id)syncLocalSelection();selected=synchronizedSelections_[id];}enumerate(args[0],args[2],1048576,[&](auto& unit){return selected.contains(unit.handle);});return vm.nothing();});
